style.css:
@-moz-document url-prefix("https://www.google.com/webhp?hl") {
body {
    background: url("https://wallpapers.com/images/featured/studio-ghibli-tykbiycf0hjhjo39.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .L3eUgb,
  #viewport {
    background: transparent !important;
  }
}

@-moz-document regexp("https://www.google.com/search?q*") {
body {
    background: url("https://i.imgur.com/dtTICPo.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .L3eUgb,
  #main,
  #rcnt {
    background: transparent !important;
  }
}
